use super::icon_from_png;

/// 1x1 opaque red PNG.
const PNG_1X1_RED: &[u8] = &[
    0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, 0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44, 0x52,
    0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x02, 0x00, 0x00, 0x00, 0x90, 0x77, 0x53,
    0xDE, 0x00, 0x00, 0x00, 0x0C, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9C, 0x63, 0xF8, 0xCF, 0xC0, 0x00,
    0x00, 0x03, 0x01, 0x01, 0x00, 0xC9, 0xFE, 0x92, 0xEF, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4E,
    0x44, 0xAE, 0x42, 0x60, 0x82,
];

#[test]
fn icon_from_png_decodes_rgba_png() {
    icon_from_png(PNG_1X1_RED).expect("1x1 png should decode");
}

#[test]
fn icon_from_png_downsamples_large_rgba() {
    let png = {
        let mut buf = Vec::new();
        let image = image::RgbaImage::from_pixel(256, 256, image::Rgba([1, 2, 3, 255]));
        image
            .write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Png)
            .expect("encode png");
        buf
    };
    icon_from_png(&png).expect("256px png should downsample");
}

#[test]
fn icon_from_png_rejects_invalid_bytes() {
    assert!(icon_from_png(b"not a png").is_err());
}
